// Build pipeline/stage ID-to-Name lookup maps from the API response.
// Pass through pagination data from Edit Fields so the loop works.
const pipelinesData = $input.first().json;
const pipelines = pipelinesData.pipelines || [];
const stageMap = {};
const pipelineMap = {};

for (const p of pipelines) {
  pipelineMap[p.id] = p.name;
  for (const s of (p.stages || [])) {
    stageMap[s.id] = s.name;
  }
}

const editFields = $('Edit Fields').first().json;
return [{
  json: {
    page: editFields.page,
    limit: editFields.limit,
    locationId: editFields.locationId,
    _pipelineMap: pipelineMap,
    _stageMap: stageMap
  }
}];

// Build the HTTP request body with guaranteed correct types.
// Runs in V8 — completely bypasses n8n's expression parser.
const page = Number($input.first().json.page);
const limit = Number($input.first().json.limit);
const locationId = String($input.first().json.locationId);

return [{
  json: {
    locationId: locationId,
    limit: limit,
    page: page
  }
}];

// Resolve pipeline & stage names using the lookup from Build Pipe Map
const maps = $('Build Pipe Map').first().json;
const pipelineMap = maps._pipelineMap || {};
const stageMap = maps._stageMap || {};

return items.map(item => {
  const o = item.json;

  const safeStr = (v) => {
    if (v === undefined || v === null) return null;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s === '' || s.toLowerCase() === 'null') return null;
      return s;
    }
    return String(v);
  };

  const safeNum = (v) => {
    if (v === undefined || v === null) return null;
    if (typeof v === 'number') return v;
    const s = String(v).trim();
    if (s === '' || s.toLowerCase() === 'null') return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  };

  return {
    json: {
      client_id: "health_hax",

      opportunity_id: safeStr(o.id ?? o.opportunityId),
      location_id: safeStr(o.locationId),
      contact_id: safeStr(o.contactId),

      pipeline_id: safeStr(o.pipelineId),
      pipeline_stage_id: safeStr(o.pipelineStageId),
      pipeline_name: pipelineMap[o.pipelineId] || null,
      pipeline_stage_name: stageMap[o.pipelineStageId] || null,

      status: safeStr(o.status),
      name: safeStr(o.name),

      monetary_value: safeNum(o.monetaryValue ?? o.value),

      created_at_str: safeStr(o.createdAt),
      updated_at_str: safeStr(o.updatedAt),
      closed_at_str: safeStr(o.closedAt),

      raw: JSON.stringify(o).replace(/'/g, "''"),
      pulled_at_ts: new Date().toISOString()
    }
  };
});

// After Snowflake processes all items from this page,
// prepare pagination state for the next page.
const currentPage = $('Build Request Body').first().json.page;
const limit = $('Build Request Body').first().json.limit;
const locationId = $('Build Request Body').first().json.locationId;

return [{
  json: {
    page: currentPage + 1,
    limit: limit,
    locationId: locationId
  }
}];
